/**
 * The resource a nav-level permission question is asked about. Nav items are
 * asked "could this actor do this at all in this org?", so the resource is
 * always the actor's own org, shaped for the action's resource kind.
 */
function navResource(action: PermissionAction, actor: Actor): PermissionResource {
  const [domain] = action.split(":");
  switch (domain) {
    case "org":
      return action === "org:manage_billing"
        ? { kind: "billing", orgId: actor.orgId }
        : { kind: "organization", orgId: actor.orgId };
    case "activity":
      return { kind: "activity", orgId: actor.orgId };
    case "notification":
      return { kind: "notification", orgId: actor.orgId, recipientId: actor.userId };
    case "webhook":
      return { kind: "webhook", orgId: actor.orgId, webhookId: null };
    default:
      // member / project / issue / comment nav entries are org-wide questions.
      return { kind: "organization", orgId: actor.orgId };
  }
}

/**
 * A snapshot is normally complete, but a client provider may be holding one
 * serialised before a flag existed. Fall back to evaluating the flag directly
 * with the conservative context we can build from the actor alone.
 */
function flagAllows(
  flag: FeatureFlagKey,
  actor: Actor,
  flags: FeatureFlagSnapshot,
): boolean {
  const snapshotted: boolean | undefined = flags[flag];
  if (typeof snapshotted === "boolean") return snapshotted;
  return isEnabled(flag, {
    orgId: actor.orgId,
    userId: actor.userId,
    plan: "free",
    role: actor.role,
  });
}

/**
 * Filters a nav tree down to what `actor` may see, recursing into children.
 * A parent whose every child was filtered away and which has no destination
 * of its own is dropped too, so the sidebar never renders an empty group.
 */
export function visibleNav(
  items: readonly NavItem[],
  actor: Actor,
  flags: FeatureFlagSnapshot,
): readonly NavItem[] {
  const visible: NavItem[] = [];

  for (const item of items) {
    if (item.flag !== undefined && !flagAllows(item.flag, actor, flags)) {
      continue;
    }
    if (item.action !== undefined && !can(actor, item.action, navResource(item.action, actor))) {
      continue;
    }

    if (item.children === undefined) {
      visible.push(item);
      continue;
    }

    const children = visibleNav(item.children, actor, flags);
    if (children.length === 0 && item.segment === "") continue;
    visible.push({ ...item, children });
  }

  return visible;
}
/**
 * Global user rows. The only repository that is NOT tenant scoped — users exist across organizations.
 */
import { eq, inArray } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toUser } from "./_mappers";
import type { UpdateProfileInput } from "@/schemas/member";
import type { UserId } from "@/types/common";
import type { User } from "@/types/member";

export async function findUserById(userId: UserId): Promise<User | null> {
  const rows = getDb().select().from(users).where(eq(users.id, userId)).all();
  const row = rows.at(0);
  return row ? toUser(row) : null;
}

export async function findUserByEmail(email: string): Promise<User | null> {
  const rows = getDb()
    .select()
    .from(users)
    .where(eq(users.email, email.toLowerCase()))
    .all();
  const row = rows.at(0);
  return row ? toUser(row) : null;
}

export async function insertUser(input: {
  email: string;
  name: string;
  passwordHash: string;
}): Promise<User> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(users)
    .values({
      id: newId(),
      email: input.email.toLowerCase(),
      name: input.name,
      passwordHash: input.passwordHash,
      avatarUrl: null,
      timezone: "UTC",
      emailVerifiedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toUser(row);
}

export async function updateUser(
  userId: UserId,
  patch: UpdateProfileInput,
): Promise<User> {
  const row = getDb()
    .update(users)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.avatarUrl === undefined ? {} : { avatarUrl: patch.avatarUrl }),
      ...(patch.timezone === undefined ? {} : { timezone: patch.timezone }),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(users.id, userId))
    .returning()
    .get();

  if (!row) throw new Error(`User ${userId} not found`);
  return toUser(row);
}

/**
 * The password hash never travels on the `User` domain type — nothing outside
 * `AuthService` may see it — so login reads it through this narrow accessor.
 *
 * Not in the manifest: added because `User` deliberately omits the column and
 * credential login has no other way to reach it.
 */
export async function findPasswordHash(
  userId: UserId,
): Promise<string | null> {
  const row = getDb()
    .select({ passwordHash: users.passwordHash })
    .from(users)
    .where(eq(users.id, userId))
    .get();
  return row?.passwordHash ?? null;
}

/** Counterpart of `findPasswordHash`, used by the password-reset flow. */
export async function updatePasswordHash(
  userId: UserId,
  passwordHash: string,
): Promise<void> {
  getDb()
    .update(users)
    .set({ passwordHash, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(users.id, userId))
    .run();
}

/** Batch fetch used by every list view that decorates rows with their author. */
export async function findUsersByIds(
  userIds: readonly UserId[],
): Promise<readonly User[]> {
  if (userIds.length === 0) return [];
  const rows = getDb()
    .select()
    .from(users)
    .where(inArray(users.id, [...userIds]))
    .all();
  return rows.map(toUser);
}
/**
 * Sidebar + top bar composition for the tenant subtree.
